-- ===== Inventarios: carga inicial del catálogo de productos dentales (Guatemala) =====
-- Tipos de producto de materiales e insumos, y 221 productos (medicamentos, materiales, insumos e instrumental)
-- clasificados por tipo de producto y presentación. Sin marca ni costo (se completan según el proveedor).
-- Sede 2-01 y bodega general de esa sede. Se puede ejecutar varias veces: no duplica.
insert into public.inv_tipos_producto (nombre, descripcion, ejemplos, requiere_receta, localidad_id, organizacion_id)
select x.nombre, x.descripcion, x.ejemplos, false, l.id, l.organizacion_id
  from (values
  ('Resinas compuestas', 'Restauraciones directas estéticas fotopolimerizables.', 'Resina nanohíbrida, resina fluida, bulk fill, sellador de fosas y fisuras'),
  ('Adhesivos y grabadores', 'Grabado ácido y adhesión a esmalte y dentina.', 'Ácido fosfórico 37%, adhesivo universal, silano'),
  ('Ionómeros de vidrio', 'Restauraciones, bases y cementación con liberación de flúor.', 'Ionómero restaurador, cementante, modificado con resina'),
  ('Cementos dentales', 'Cementación de coronas, protección pulpar y obturaciones temporales.', 'Cemento de resina dual, fosfato de zinc, IRM, MTA'),
  ('Materiales de impresión', 'Toma de impresiones y vaciado de modelos.', 'Alginato, siliconas de adición y condensación, yeso tipo III y IV'),
  ('Materiales de endodoncia', 'Instrumentación y obturación de conductos.', 'Limas K y H, limas NiTi, gutapercha, conos de papel, selladores'),
  ('Profilaxis e higiene oral', 'Limpieza dental profesional e higiene en casa.', 'Pasta profiláctica, copas, hilo dental, cepillos interdentales'),
  ('Ortodoncia', 'Aparatología fija y sus accesorios.', 'Brackets, tubos, arcos NiTi y acero, ligaduras, cadenas'),
  ('Prótesis y laboratorio', 'Prótesis provisionales y definitivas, trabajo de laboratorio.', 'Acrílicos, dientes de acrílico, coronas provisionales, hilo retractor'),
  ('Cirugía y periodoncia', 'Suturas, injertos y materiales quirúrgicos.', 'Suturas, hueso liofilizado, membranas de colágeno, hojas de bisturí'),
  ('Bioseguridad y esterilización', 'Protección personal, desinfección y esterilización.', 'Guantes, mascarillas, bolsas de esterilización, desinfectantes'),
  ('Insumos descartables', 'Material de un solo uso en la atención.', 'Agujas dentales, eyectores, rollos de algodón, dique de goma, matrices'),
  ('Instrumental', 'Instrumental clínico y quirúrgico reutilizable.', 'Espejo, explorador, fórceps, elevadores, curetas, fresas'),
  ('Radiología dental', 'Toma y procesamiento de radiografías.', 'Películas periapicales, protectores de sensor, posicionadores')
  ) x (nombre, descripcion, ejemplos)
  cross join (select l.id, l.organizacion_id from public.org_localidades l join public.organizaciones o on o.id = l.organizacion_id where o.codigo = '2' and l.codigo = '1') l
 where not exists (select 1 from public.inv_tipos_producto t where lower(t.nombre) = lower(x.nombre) and t.localidad_id = l.id);

